  function pzIsMine(authorText) {
    var a = (authorText || '').trim();
    try {
      var st = window.activeStore && window.activeStore();
      if (st) {
        var me = st.get('lbl-user') || '我', ta = st.get('lbl-partner') || 'TA';
        if (a === me && a !== ta) return true;
        if (a === ta && a !== me) return false;
      }
    } catch (e) {}
    return /我|自己/.test(a);
  }

