  function injectCss() {
    if (document.getElementById('mail-postal-css')) return;
    var st = document.createElement('style');
    st.id = 'mail-postal-css';
    st.textContent = CSS;
    document.head.appendChild(st);
  }

  function ensureFontImport(url, id) {
    var link = document.getElementById(id);
    if (!url) { if (link) link.remove(); return; }
    if (!link) {
      link = document.createElement('link');
      link.id = id;
      link.rel = 'stylesheet';
      document.head.appendChild(link);
    }
    if (link.getAttribute('href') !== url) link.setAttribute('href', url);
  }
  function fontStack(name, fallback) {
    name = (name || '').trim();
    return name ? '"' + name + '", Georgia, "Songti SC", serif' : fallback;
  }
  function applySettings() {
    var s = loadSet();
    var r = document.documentElement.style;
    var th = THEMES[s.theme] || THEMES.kraft;
    r.setProperty('--pz-kraft', th.kraft);
    r.setProperty('--pz-paper', th.paper);
    r.setProperty('--pz-ink', th.ink);
    r.setProperty('--pz-sub', th.sub);
    r.setProperty('--pz-line', th.line);
    r.setProperty('--pz-cream', th.cream);
    var customHex = /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(s.accent || '') ? s.accent : null;
    r.setProperty('--pz-red', ACCENTS[s.accent] || customHex || th.red);
    if (s.font === 'custom') {
      ensureFontImport((s.fontUrl || '').trim(), 'pz-font-link');
      r.setProperty('--pz-font', fontStack(s.fontName, 'Georgia,"Songti SC",serif'));
    } else {
      ensureFontImport('', 'pz-font-link');
      r.setProperty('--pz-font', s.font === 'sans' ? '-apple-system,"PingFang SC","Helvetica Neue",sans-serif' : 'Georgia,"Songti SC",serif');
    }
    var sz = { s: ['14px', '28px'], m: ['15.5px', '31px'], l: ['17px', '34px'] }[s.size] || ['15.5px', '31px'];
    r.setProperty('--pz-size', sz[0]);
    r.setProperty('--pz-lh', sz[1]);
    if (s.authorFont === 'custom') {
      ensureFontImport((s.authorFontUrl || '').trim(), 'pz-afont-link');
      r.setProperty('--pz-author-font', fontStack(s.authorFontName, 'Georgia,"Songti SC",serif'));
    } else {
      ensureFontImport('', 'pz-afont-link');
      r.setProperty('--pz-author-font', s.authorFont === 'sans' ? '-apple-system,"PingFang SC",sans-serif' : 'Georgia,"Songti SC",serif');
    }
    r.setProperty('--pz-author-size', (s.authorSize || 12.5) + 'px');
    r.setProperty('--pz-wax-img', 'url("' + ((s.waxImg || '').trim() || WAX_SEAL_IMG) + '")');
    r.setProperty('--pz-btn-img', 'url("' + ((s.btnImg || '').trim() || WAX_BTN_BG) + '")');
    document.documentElement.classList.toggle('pz-btn-custom', !!(s.btnImg || '').trim());
    // v29：读信底板（白卡/木桌/黑板），默认木桌（老设置里没有该字段也落到木桌）
    var rbg = s.readingBg || 'desk';
    document.documentElement.classList.toggle('pz-bg-desk', rbg === 'desk');
    document.documentElement.classList.toggle('pz-bg-board', rbg === 'board');
    document.documentElement.classList.toggle('pz-wax-custom', !!(s.waxImg || '').trim());
  }

  // ---------- :has() 旧内核回退 ----------
  var SUPPORTS_HAS = !!(window.CSS && CSS.supports && CSS.supports('selector(:has(*))'));
  function syncMaskClass() {
    if (SUPPORTS_HAS) return;
    var mask = document.getElementById('tc-mask');
    if (!mask) return;
    // 必须先 contains 再 toggle：Chromium 对「无变化的 classList 操作」也会产 mutation
    // 记录，而本函数跑在观察 tc-mask 属性（含 class）的观察器里——不设防会自激死循环
    var has = !!mask.querySelector('.mail-paper');
    if (mask.classList.contains('pz-has-paper') !== has) mask.classList.toggle('pz-has-paper', has);
  }
  // v28：信件弹层的 ✕ 挪到信纸右上角（小圆贴样式见 .pz-paper-close）。
  // tc-mask 是全站共用弹层（TA 的小问题等也在用），所以只在弹层里是信纸时移动，
  // 其他内容打开前挪回 .mg-head——ta-ask.js 每次 openTCPanel 重新绑点击，节点移动不掉绑定。
  // v29 补洞：✕ 挪进信纸后节点落在 #tc-body 里，而各弹层内容方（mail.js / ta-ask.js）
  // 重绘都是 body.innerHTML=…——会把 ✕ 节点整块销毁（读信→关掉→再开任何 tc-mask 内容，
  // ✕ 就永久消失）。所以这里发现节点没了就照原样重建一枚（id/类名/文案一致，
  // 点击行为 = 原 ta-ask 绑定的 mask.hidden=true）。
  function ensureCloseBtn(mask) {
    var btn = document.getElementById('tc-mask-close');
    if (!btn) {
      btn = document.createElement('button');
      btn.id = 'tc-mask-close';
      btn.className = 'mg-close';
      btn.type = 'button';
      btn.textContent = '✕';
      btn.addEventListener('click', function () { mask.hidden = true; });
      var head0 = mask.querySelector('.mg-head');
      if (head0) { head0.appendChild(btn); }
      else { var panel0 = mask.querySelector('.tc-panel'); if (panel0) panel0.appendChild(btn); else return btn; }
    }
    return btn;
  }
  function syncCloseBtn() {
    var mask = document.getElementById('tc-mask');
    if (!mask) return;
    var btn = ensureCloseBtn(mask);
    var paper = mask.querySelector('#tc-body .mail-paper');
    // classList 增删必须先 contains 判断：Chromium 对无变化的 add/remove 也会产
    // mutation 记录，而本函数被「观察 tc-mask 属性（含 class）」的观察器回调调用——
    // 不设防会 观察→写class→又观察 自激死循环（v28 实测抓到 attributes:tc-mask-close 刷屏）
    if (paper && !mask.hidden) {
      if (btn.parentNode !== paper) { paper.appendChild(btn); }
      if (!btn.classList.contains('pz-paper-close')) btn.classList.add('pz-paper-close');
    } else {
      var head = mask.querySelector('.mg-head');
      if (head && btn.parentNode !== head) head.appendChild(btn);
      if (btn.classList.contains('pz-paper-close')) btn.classList.remove('pz-paper-close');
    }
  }

  // ---------- 顶栏自适应（真实项目为 .chat-head/.ch-name；保留多候选兜底） ----------
  function findTopbar(pg) {
    if (!pg) return null;
    var t = pg.querySelector('.chat-head') || pg.querySelector('.cal-topbar') || pg.querySelector('[class*="topbar"]') || pg.querySelector('header');
    if (!t) {
      var kids = pg.children;   // 启发式：页面前三个子元素里第一个含返回件/按钮的块
      for (var i = 0; i < Math.min(kids.length, 3); i++) {
        if (kids[i].querySelector && kids[i].querySelector('button, .ch-back, [class*="back"]')) { t = kids[i]; break; }
      }
    }
    if (t && !t.classList.contains('cal-topbar') && !t.classList.contains('chat-head')) t.classList.add('pz-topbar');
    return t;
  }

  function resolveStamp(v, def) {
    if (v === 'none') return null;
    if (v === 'red') return STAMP_IN_DEFAULT;
    if (v === 'pink') return STAMP_OUT_DEFAULT;
    if (v && v.indexOf('data:') === 0) return v;
    return def;
  }
  function makeMark(kraft) {
    var s = loadSet();
    var img = kraft ? resolveStamp(s.stampOut, STAMP_OUT_DEFAULT) : resolveStamp(s.stampIn, STAMP_IN_DEFAULT);
    if (!img) return null;
    var m = document.createElement('span');
    m.className = 'postal-mark stamp-in';
    m.style.setProperty('--stamp-img', 'url("' + img + '")');
    return m;
  }
  function fmtMarkDate(ts) {
    var d = new Date(ts || Date.now());
    var p = function (n) { return (n < 10 ? '0' : '') + n; };
    return d.getFullYear() + '.' + p(d.getMonth() + 1) + '.' + p(d.getDate());
  }
  function stampPapers(root) {
    if (!root || !root.querySelectorAll) return;
    var papers = root.querySelectorAll('.mail-paper');
    for (var i = 0; i < papers.length; i++) {
      var p = papers[i];
      if (p.querySelector(':scope > .postal-mark')) continue;
      var authorEl = p.querySelector('.mail-paper-author');
      var titleEl = p.querySelector('.mail-paper-title');
      var dateEl = p.querySelector('.mail-paper-date');
      var isMine = authorEl && pzIsMine(authorEl.textContent);
      var mark = makeMark(isMine);
      if (!mark) continue;
      mark.style.position = 'absolute';
      mark.style.top = '10px';
      mark.style.right = '10px';
      p.appendChild(mark);
      if (titleEl && !isMine) markReadFromPaper(titleEl.textContent.trim(), dateEl ? dateEl.textContent.trim() : '');
    }
    if (papers.length) markListState();
  }

  // ---------- 已读 / 已回小戳 ----------
  function itemTitle(it) {
    var te = it.querySelector('.mail-item-title');
    if (!te) return '';
    return (te.childNodes && te.childNodes.length ? te.childNodes[0].textContent : te.textContent).trim();
  }
  function itemTime(it) { var te = it.querySelector('.mail-item-time'); return te ? te.textContent.trim() : ''; }
  // 主键：mail.js 渲染在 .mail-item 上的 data-id（稳定信件 id）；无 id 时退回 标题|时间
  function itemKey(it) {
    var id = it.dataset && it.dataset.id;
    if (id) return 'id:' + id;
    return itemTitle(it) + '|' + itemTime(it);
  }
  // 兼容迁移过来的纯标题旧条目；新记录一律 data-id
  function isReadEntry(rs, it) { return rs.indexOf(itemKey(it)) >= 0 || rs.indexOf(itemTitle(it)) >= 0; }
  // v28：缩略图主标题 = 信件自己的标题 tt（作者要求：「来自 TA」部分换成如「想你了」，
  // 下面一行仍是正文摘要）。tt 从本地存储的信件数组按 data-id 查（LS 剥图快照保留 tt）；
  // 查不到（无 id / 快照未落 LS）退回正文首句。只替换标题开头文本节点，
  // mail.js 拼进去的 新来信/已回信/对方已回信 小戳原样保留。
  var ltCache = { key: null, raw: null, map: {} };
  function letterTT(id) {
    var k = (function () { var p = pzScope(); return p ? p + ':mail-letters' : 'mail-letters'; })();
    var raw = '';
    try { raw = localStorage.getItem(k) || ''; } catch (e) { return ''; }
    if (ltCache.key !== k || ltCache.raw !== raw) {
      var map = {};
      try {
        var arr = JSON.parse(raw);
        if (arr && arr.length) for (var i = 0; i < arr.length; i++) {
          if (arr[i] && arr[i].id != null) map[String(arr[i].id)] = arr[i].tt || '';
        }
      } catch (e) {}
      ltCache = { key: k, raw: raw, map: map };
    }
    return ltCache.map[id] || '';
  }
  function rewriteTitle(it) {
    var te = it.querySelector('.mail-item-title');
    var de = it.querySelector('.mail-item-desc');
    if (!te || !de) return;
    var id = it.dataset && it.dataset.id;
    var want = (id && letterTT(id)) || (de.textContent || '').trim();
    if (!want) return;
    // 标题包进 .pz-tt 弹性缩略（长题省略号），小戳 flex:none 永远完整露出；
    // 只剥开头的「来自 xx / 寄给 xx」文本节点，mail.js 的小戳节点原地保留
    var tt = te.querySelector('.pz-tt');
    if (!tt) {
      tt = document.createElement('span');
      tt.className = 'pz-tt';
      while (te.firstChild && te.firstChild.nodeType === 3) te.removeChild(te.firstChild);
      te.insertBefore(tt, te.firstChild);
    }
    if (tt.textContent !== want) tt.textContent = want;
  }
  // 开信时记录已读：优先用捕获到的被点 item 的 data-id；否则在收件箱里按 标题+时间 反查
  var lastOpenedKey = '';
  function markReadFromPaper(title, dateText) {
    var key = lastOpenedKey || '';
    lastOpenedKey = '';
    if (!key) {
      var box = document.getElementById('mail-in-list');
      if (box) {
        var items = box.querySelectorAll('.mail-item');
        var cand = null;
        for (var i = 0; i < items.length; i++) {
          if (itemTitle(items[i]) !== title) continue;
          if (dateText && itemTime(items[i]) === dateText) { cand = items[i]; break; }
          if (!cand) cand = items[i];
        }
        if (cand) key = itemKey(cand);
      }
    }
    if (!key) key = title;
    markReadKey(key);
  }
  function markListState() {
    var rs = readSet();
    var jobs = [['mail-in-list', 'in'], ['mail-out-list', 'out']];
    for (var k = 0; k < jobs.length; k++) {
      var box = document.getElementById(jobs[k][0]);
      if (!box) continue;
      var items = box.querySelectorAll('.mail-item');
      for (var i = 0; i < items.length; i++) {
        var it = items[i];
        attachSwipe(it);
        applyTape(it);
        rewriteTitle(it);
        var hasNew = !!it.querySelector('.mail-tag.new');
        var hasAnyTag = !!it.querySelector('.mail-tag');
        if (jobs[k][1] === 'in') {
          var wasRead = !hasNew || isReadEntry(rs, it);
          it.classList.toggle('postal-read', wasRead);
          it.classList.remove('postal-replied');
        } else {
          it.classList.toggle('postal-replied', hasAnyTag && !hasNew);
        }
      }
    }
  }

  // ---------- 滑动操作：左滑删除 / 右滑收藏 ----------
  // 用户口径（2026-10-17 二次确认）：信纸页脚只留「提笔回信」；收藏/删除走列表滑动，
  // 关闭用信纸右上角的 ✕。滑动 = 先打开该信（mail.js 列表代理）→ 点页脚原按钮：
  //   删除：deleteLetter 自己弹确认框；收藏：addMyFavItem 后由主题代点关闭。
  function openItemLetter(item, cb) {
    item.click();
    setTimeout(cb, 90);
  }
  function swipeDelete(item) {
    openItemLetter(item, function () {
      var b = document.getElementById('mail-del-btn');
      if (b) { b.click(); return; }
      if (window.console && console.warn) console.warn('[mail-postal] 弹层中未找到 #mail-del-btn，删除未触发。');
    });
  }
  function swipeFav(item) {
    openItemLetter(item, function () {
      var b = document.getElementById('mail-fav-btn');
      if (!b) {
        if (window.console && console.warn) console.warn('[mail-postal] 弹层中未找到 #mail-fav-btn，收藏未触发。');
        return;
      }
      b.click();
      setTimeout(function () {
        var c = document.getElementById('mail-close2');
        if (c) c.click();
      }, 320);
    });
  }
  function attachSwipe(item) {
    if (item.__pzSwipe || !item.parentNode) return;
    item.__pzSwipe = 1;
    var inInbox = !!(item.closest && item.closest('#mail-in-list'));   // 收藏仅限收件箱
    var wrap = document.createElement('div');
    wrap.className = 'pz-swipe-wrap';
    item.parentNode.insertBefore(wrap, item);
    var del = document.createElement('button');
    del.className = 'pz-swipe pz-swipe-del'; del.type = 'button'; del.textContent = '删除';
    wrap.appendChild(del);
    var fav = null;
    if (inInbox) {
      fav = document.createElement('button');
      fav.className = 'pz-swipe pz-swipe-fav'; fav.type = 'button'; fav.textContent = '收藏';
      wrap.appendChild(fav);
    }
    wrap.appendChild(item);

    // 胶带热区：点一下重新选胶带（不触发开信）
    if (!item.querySelector('.pz-tape-hit')) {
      var hit = document.createElement('i');
      hit.className = 'pz-tape-hit';
      hit.title = '点击换胶带';
      hit.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        openTapeSheet(item, true);
      });
      item.appendChild(hit);
    }

    var sx = null, sy = 0, dx = 0, dragging = false, suppress = false, opened = 0;
    function setX(v) { item.style.transform = 'translateX(' + v + 'px)'; }
    function close() { opened = 0; setX(0); }
    item.addEventListener('pointerdown', function (e) { sx = e.clientX; sy = e.clientY; dx = 0; dragging = false; item.style.transition = 'none'; });
    window.addEventListener('pointermove', function (e) {
      if (sx === null) return;
      dx = e.clientX - sx;
      if (!dragging && Math.abs(dx) > 8 && Math.abs(dx) > Math.abs(e.clientY - sy)) { dragging = true; }
      if (dragging) { e.preventDefault(); setX(Math.max(-110, Math.min(fav ? 110 : 0, dx))); }
    }, { passive: false });
    window.addEventListener('pointerup', function () {
      if (sx === null) return;
      item.style.transition = '';
      if (dragging) {
        suppress = true;
        if (dx <= -60) { opened = -1; setX(-84); }
        else if (dx >= 60 && fav) { opened = 1; setX(84); }
        else close();
      }
      sx = null; dragging = false;
    });
    item.addEventListener('click', function (e) {
      if (suppress) { e.stopPropagation(); e.preventDefault(); suppress = false; return; }
      if (opened) { e.stopPropagation(); e.preventDefault(); close(); }
    }, true);
    del.addEventListener('click', function () { close(); swipeDelete(item); });
    if (fav) fav.addEventListener('click', function () { close(); swipeFav(item); });
  }

  function watchLists() {
    ['mail-in-list', 'mail-out-list'].forEach(function (id) {
      var box = document.getElementById(id);
      if (!box || box.__postalWatched) return;
      box.__postalWatched = true;
      new MutationObserver(markListState).observe(box, { childList: true, subtree: true });
      // 捕获阶段记录被点开的那封信（mail.js 打开是同步渲染，弹层观察器随后用到）
      box.addEventListener('click', function (e) {
        var it = e.target && e.target.closest ? e.target.closest('.mail-item') : null;
        if (it) lastOpenedKey = itemKey(it);
      }, true);
    });
  }

  // ---------- 相册图自动抠底（黑底/白底 JPG） ----------
  // 原理：采样四边边缘像素估计背景色并测均匀度；均匀则按「到背景色的距离」
  // 生成软 alpha，并对半透明边缘做去底色污染。边框不均匀（照片/花纹底）自动放弃。
  // 返回值：true = 已抠底（调用方应存 PNG 保留透明）；false = 放弃。
  function autoKeyOut(cv) {
    var ctx = cv.getContext('2d');
    var w = cv.width, h = cv.height;
    if (w < 16 || h < 16) return false;
    var d, px;
    try { d = ctx.getImageData(0, 0, w, h); } catch (e) { return false; }
    px = d.data;
    var B = 3, i, x, y;
    var rr = [], gg = [], bb = [], transparent = 0, total = 0;
    for (y = 0; y < h; y++) for (x = 0; x < w; x++) {
      if (x >= B && y >= B && x < w - B && y < h - B) continue;
      i = (y * w + x) * 4; total++;
      if (px[i + 3] < 250) transparent++;
      rr.push(px[i]); gg.push(px[i + 1]); bb.push(px[i + 2]);
    }
    if (transparent > total * 0.05) return false;  // 原图自带透明通道，不动
    function med(a) { a.sort(function (p, q) { return p - q; }); return a[Math.floor(a.length / 2)]; }
    var bg = [med(rr), med(gg), med(bb)];
    var uni = 0;
    for (i = 0; i < rr.length; i++) {
      var dr0 = rr[i] - bg[0], dg0 = gg[i] - bg[1], db0 = bb[i] - bg[2];
      uni += Math.sqrt(dr0 * dr0 + dg0 * dg0 + db0 * db0);
    }
    if (uni / rr.length > 24) return false;  // 边框颜色杂乱，不是纯色底，放弃
    var T0 = 26, T1 = 80;
    for (i = 0; i < px.length; i += 4) {
      var dr = px[i] - bg[0], dg = px[i + 1] - bg[1], db = px[i + 2] - bg[2];
      var dist = Math.sqrt(dr * dr + dg * dg + db * db);
      var t = (dist - T0) / (T1 - T0); t = t < 0 ? 0 : t > 1 ? 1 : t;
      var a = t * t * (3 - 2 * t);   // smoothstep 软边
      if (a > 0.08) {                // 去边色污染：把半透明像素里混入的背景色减掉
        px[i]     = Math.max(0, Math.min(255, (px[i]     - bg[0] * (1 - a)) / a));
        px[i + 1] = Math.max(0, Math.min(255, (px[i + 1] - bg[1] * (1 - a)) / a));
        px[i + 2] = Math.max(0, Math.min(255, (px[i + 2] - bg[2] * (1 - a)) / a));
      }
      px[i + 3] = Math.round(a * 255);
    }
    ctx.putImageData(d, 0, 0);
    return true;
  }

